import java.time.LocalDate;

public class Main {
    public static void main(String[] args) {
        LocalDate d = LocalDate.of(2024, 5, 3);

        System.out.println("そのまま      : " + d);
        System.out.println("年            : " + d.getYear());
        System.out.println("月（数字）     : " + d.getMonthValue());
        System.out.println("月（enum）     : " + d.getMonth());
        System.out.println("日            : " + d.getDayOfMonth());
        System.out.println("曜日          : " + d.getDayOfWeek());
        System.out.println("その月の日数   : " + d.lengthOfMonth());
        System.out.println("うるう年か     : " + d.isLeapYear());

        System.out.println("parse         : " + LocalDate.parse("2000-01-01"));
    }
}

import java.time.LocalDate;

public class Main {
    public static void main(String[] args) {
        int[] years = {2000, 1900, 2024, 2023, 2100};
        for (int y : years) {
            System.out.println(y + " はうるう年か: " + LocalDate.of(y, 1, 1).isLeapYear());
        }

        try {
            LocalDate.of(2023, 2, 29);
        } catch (Exception e) {
            System.out.println("2023-02-29 → " + e.getClass().getSimpleName());
        }

        try {
            LocalDate.of(2024, 13, 1);
        } catch (Exception e) {
            System.out.println("13月 → " + e.getClass().getSimpleName());
        }
    }
}

