import java.time.LocalDate;

public class Main {
    public static void main(String[] args) {
        LocalDate d = LocalDate.of(2024, 5, 3);

        d.plusDays(10);                       // 捨てている
        System.out.println("捨てた後  : " + d);

        LocalDate later = d.plusDays(10);     // 受け取っている
        System.out.println("受け取り  : " + later);
        System.out.println("元の d    : " + d);

        d = d.plusDays(10);                   // 入れ直している
        System.out.println("入れ直し  : " + d);

        System.out.println("--- 比較 ---");
        System.out.println(later.isBefore(d) + " / " + later.isEqual(d));
    }
}

import java.time.LocalDate;

public class Main {
    public static void main(String[] args) {
        System.out.println("2024-01-31 +1月 : " + LocalDate.of(2024, 1, 31).plusMonths(1));
        System.out.println("2023-01-31 +1月 : " + LocalDate.of(2023, 1, 31).plusMonths(1));
        System.out.println("2023-03-31 +1月 : " + LocalDate.of(2023, 3, 31).plusMonths(1));
        System.out.println("2024-05-03 +1月 : " + LocalDate.of(2024, 5, 3).plusMonths(1));

        System.out.println("--- 足して引くと元に戻らない ---");
        LocalDate d = LocalDate.of(2024, 1, 31);
        System.out.println(d + " → " + d.plusMonths(1) + " → " + d.plusMonths(1).minusMonths(1));

        System.out.println("--- plusDays は素直 ---");
        System.out.println(LocalDate.of(2024, 12, 31).plusDays(1));
    }
}

