import java.time.LocalDate;
import java.time.Period;
import java.time.temporal.ChronoUnit;

public class Main {
    public static void main(String[] args) {
        LocalDate from = LocalDate.of(2020, 1, 1);
        LocalDate to = LocalDate.of(2024, 3, 15);

        Period p = Period.between(from, to);
        System.out.println("年     : " + p.getYears());
        System.out.println("月     : " + p.getMonths());
        System.out.println("日(余り): " + p.getDays());

        long days = ChronoUnit.DAYS.between(from, to);
        System.out.println("総日数  : " + days);
        System.out.println("総月数  : " + ChronoUnit.MONTHS.between(from, to));
        System.out.println("総年数  : " + ChronoUnit.YEARS.between(from, to));
    }
}

import java.time.Duration;
import java.time.LocalDate;
import java.time.LocalDateTime;
import java.time.Period;
import java.time.temporal.ChronoUnit;

public class Main {
    public static void main(String[] args) {
        LocalDate a = LocalDate.of(2024, 1, 31);
        LocalDate b = LocalDate.of(2024, 3, 1);

        Period p = Period.between(a, b);
        System.out.println(p.getYears() + "年 " + p.getMonths() + "か月 " + p.getDays() + "日");
        System.out.println("総日数: " + ChronoUnit.DAYS.between(a, b));

        System.out.println("--- 時間の差 ---");
        Duration d = Duration.between(
                LocalDateTime.of(2024, 5, 3, 9, 0),
                LocalDateTime.of(2024, 5, 3, 17, 30));
        System.out.println(d.toHours() + "時間 = " + d.toMinutes() + "分");
    }
}

