        LocalDateTime dt = LocalDateTime.of(2024, 5, 3, 13, 7);

        System.out.println("MM（月）  : " + dt.format(DateTimeFormatter.ofPattern("MM")));
        System.out.println("mm（分）  : " + dt.format(DateTimeFormatter.ofPattern("mm")));
        System.out.println("HH（24時）: " + dt.format(DateTimeFormatter.ofPattern("HH")));
        System.out.println("hh（12時）: " + dt.format(DateTimeFormatter.ofPattern("hh")));

        System.out.println("--- 秒が 0 なら省略される ---");
        System.out.println(LocalDateTime.of(2024, 5, 3, 9, 5));
        System.out.println(LocalDateTime.of(2024, 5, 3, 9, 5, 30));
    }
}

